// Clean and validate what the AI returned.
// Output: one item per valid UPCOMING deadline, or a single { valid: false } item.
const out = $input.first().json.output || {};
const list = Array.isArray(out.deadlines) ? out.deadlines : [];
const src = $('When called by main workflow').first().json;
const cutoff = $now.setZone('Europe/Paris').startOf('day');   // deadlines before today are already over

const results = [];
let pastCount = 0;
for (const d of list) {
  const title = String(d.title || '').trim();
  const date = String(d.due_date || '').trim();
  let time = String(d.due_time || '').trim();

  if (!title) continue;                                  // nothing to save
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) continue;        // not a real date
  const timeGiven = /^\d{1,2}:\d{2}$/.test(time);
  if (!timeGiven) time = '23:59';                        // default: end of day
  if (time.length === 4) time = '0' + time;               // 9:00 -> 09:00

  const dt = DateTime.fromISO(`${date}T${time}`, { zone: 'Europe/Paris' });
  if (!dt.isValid) continue;
  if (dt < cutoff) { pastCount++; continue; }            // skip deadlines that already passed

  results.push({
    json: {
      valid: true,
      course: String(d.course || '').trim() || 'Unknown course',
      title,
      due_at: dt.toISO(),
      time_given: timeGiven,
      source: src.file_kind || src.source || 'text',      // photo / pdf / text / web
      added_by: src.added_by || 'unknown',
      past_skipped: pastCount,
    },
  });
}

if (results.length === 0) return [{ json: { valid: false, past_skipped: pastCount } }];
return results;

// One reply covering saved, flagged, skipped and already-over deadlines.
const all = $('Code: check duplicates').all().map(i => i.json);
const past = Math.max(0, ...$('Code: normalise dates').all().map(i => i.json.past_skipped || 0));
const fmt = iso => DateTime.fromISO(iso, { zone: 'Europe/Paris' }).setLocale('en').toFormat('ccc d LLL, HH:mm');
const line = d => `• ${d.course} – ${d.title}: ${fmt(d.due_at)}`;

const saved = all.filter(d => d.status === 'new');
const conflicts = all.filter(d => d.status === 'conflict');
const dups = all.filter(d => d.status === 'duplicate');
const s = n => (n > 1 ? 's' : '');

const parts = [];
if (saved.length) parts.push(`✅ Saved ${saved.length} deadline${s(saved.length)}:\n` + saved.map(line).join('\n'));
if (conflicts.length) parts.push(`⚠️ Saved with a conflict flag – another date was already saved, check with the teacher:\n` +
  conflicts.map(d => `${line(d)}\n   (already saved: ${fmt(d.previous_due_at)})`).join('\n'));
if (dups.length) parts.push(`📌 This deadline is already recorded:\n` + dups.map(line).join('\n'));
if (past) parts.push(`📅 Skipped ${past} deadline${s(past)} that ${past > 1 ? 'are' : 'is'} already over.`);

const reply = parts.join('\n\n') + '\n\nSend /deadlines to see the full list.';
return [{ json: { reply, saved: saved.length + conflicts.length, skipped: dups.length } }];

// Compare each new deadline with what is already saved.
// status = new | duplicate (same deadline + same day) | conflict (same deadline, different day)
const incoming = $('Code: normalise dates').all().map(i => i.json);
const existing = $input.all().map(i => i.json).filter(r => r && r.id);

// Loose matching so "Final quiz (exam)" = "Final quiz" and "e-business" = "E business"
const key = s => String(s || '').toLowerCase().replace(/\([^)]*\)/g, ' ').normalize('NFD')
  .replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '');
const sameTitle = (a, b) => { const x = key(a), y = key(b); return !!x && !!y && (x === y || x.includes(y) || y.includes(x)); };
const unknown = c => key(c) === 'unknowncourse' || key(c) === '';
const sameCourse = (a, b) => unknown(a) || unknown(b) || key(a) === key(b);
const day = iso => DateTime.fromISO(iso, { zone: 'Europe/Paris' }).toISODate();

const seen = [];   // also catches the same deadline twice in one message
const out = [];
for (const d of incoming) {
  const matches = existing.concat(seen).filter(r => sameTitle(r.title, d.title) && sameCourse(r.course, d.course));
  let status = 'new';
  let previous_due_at = null;
  if (matches.some(r => day(r.due_at) === day(d.due_at))) status = 'duplicate';
  else if (matches.length) { status = 'conflict'; previous_due_at = matches[0].due_at; }
  out.push({ json: { ...d, status, previous_due_at } });
  seen.push(d);
}
return out;

// Combine the caption with what Claude read in the file, then continue like a typed message.
const p = $('When called by main workflow').first().json;
const r = $input.first().json || {};

// Pull the text out of the AI answer, whatever shape it comes in.
function textOf(x) {
  if (x == null) return '';
  if (typeof x === 'string') return x;
  if (Array.isArray(x)) return x.map(textOf).join('\n');
  if (typeof x === 'object') {
    for (const k of ['text', 'content', 'output', 'message', 'response']) {
      if (x[k] != null) return textOf(x[k]);
    }
  }
  return '';
}
const read = textOf(r).trim();
const caption = String(p.text || p.caption || '').trim();
const text = [caption, read === 'NONE' ? '' : read].filter(Boolean).join('\n');
return [{ json: { text, added_by: p.added_by, source: p.file_kind } }];
